function h(name) { return String(request.getOriginalHeader(name) || ''); }
if (h('X-Encrypt').toLowerCase() !== 'true') return null;
var version = h('X-Version'), user = h('X-User-Id'), machine = h('X-Machine-Id');
var password = user + '_' + machine;
var salt = Bytes.utf8('uce:test:gcm:v1:' + version + ':' + machine);
var key = Crypto.pbkdf2(password, salt, 50000, 256);
var aad = Bytes.utf8([request.getMethod(), request.getPath(), version, user, machine, h('X-Timestamp')].join('|'));
var envelope = Bytes.fromBase64(content.replace(/\s+/g, ''));
if (envelope.length < 28) throw new Error('Invalid synthetic GCM envelope');
return Bytes.text(Crypto.aesGcmDecrypt(key, envelope.slice(0,12), envelope.slice(12), aad));

